class TestTestModels5GDownlinkPageViewPanel(unittest.TestCase):
    @patch('taf.ul.oam.selenium_coam.common.common.WebDriver')
    def setUp(self, mock_web_driver):
        self.tested_page_view_panel = TestModels5GDownlinkPageViewPanel()

    def test_start_test(self):
        expected_local_cell = 'NRCELL-4'
        expected_test_model = 'NR-FR2-TM2'
        expected_p_max = 26
        expected_timeout = 50
        expected_polarization = 'P_both'
        expected_physical_cell_id = 5

        self.tested_page_view_panel.select_element_from_dropdown_list_by_text_and_click = mock.Mock()
        self.tested_page_view_panel.insert_text_to_enable_element = mock.Mock()
        self.tested_page_view_panel.click_enabled_element = mock.Mock()

        self.tested_page_view_panel.start_test(local_cell=expected_local_cell, test_model=expected_test_model,
                                               p_max=expected_p_max, timeout=expected_timeout,
                                               polarization=expected_polarization,
                                               physical_cell_id=expected_physical_cell_id)

        self.tested_page_view_panel.select_element_from_dropdown_list_by_text_and_click.assert_has_calls(
            [call(expected_local_cell,
                  (By.XPATH, '//div[contains(text(), "Local cell:")]/parent::*//button'),
                  (By.XPATH, '//div[contains(text(), "Local cell:")]/parent::*//ul//li'),
                  expected_timeout),
             call(expected_test_model,
                  (By.XPATH, '//div[contains(text(), "Test model:")]/parent::*//button'),
                  (By.XPATH, '//div[contains(text(), "Test model:")]/parent::*//ul//li'),
                  expected_timeout),
             call(expected_polarization,
                  (By.XPATH, '//div[contains(text(), "Polarization:")]/parent::*//button'),
                  (By.XPATH, '//div[contains(text(), "Polarization:")]/parent::*//ul//li'),
                  expected_timeout)
             ])
        self.tested_page_view_panel.insert_text_to_enable_element.assert_has_calls(
            [call((By.XPATH, '//div[contains(text(), "pMax:")]/parent::*//input'),
                  str(expected_p_max),
                  expected_timeout),
             call((By.XPATH, '//div[contains(text(), "Physical cell ID:")]/parent::*//input'),
                  str(expected_physical_cell_id),
                  expected_timeout)])
        self.tested_page_view_panel.click_enabled_element.assert_called_once_with(
            (By.XPATH, '//button[contains(text(), "Start Test")]'), expected_timeout)

    def test_start_test_without_optional_params(self):
        expected_local_cell = 'NRCELL-4'
        expected_test_model = 'NR-FR2-TM2'
        expected_p_max = 26
        expected_timeout = 50
